typedef struct {NSMutableSet *names;dispatch_semaphore_t ready;dispatch_queue_t queue;char path[1024];unsigned flags,callbacks,retains,releases;FSEventStreamEventId last;BOOL reenter,didReenter,stopInCallback,invalidateInCallback,syncReenter;pthread_t runloopThread;} Context;
