static void writeFile(Context *c,const char *name){char path[1200];snprintf(path,sizeof(path),"%s/%s",c->path,name);int fd=open(path,O_WRONLY|O_CREAT|O_TRUNC,0600);CHECK(fd>=0);CHECK(write(fd,"actual-file-data",16)==16);CHECK(close(fd)==0);}
static void callback(ConstFSEventStreamRef stream,void *info,size_t count,void *paths,const FSEventStreamEventFlags flags[],const FSEventStreamEventId ids[]){@autoreleasepool{
 Context *c=info;CHECK(count>0);if(c->queue)CHECK(dispatch_get_specific(c)==c);else CHECK(pthread_equal(c->runloopThread,pthread_self()));
