 @synchronized(c->names){c->callbacks++;for(size_t i=0;i<count;i++){NSString *path;
  if(!(c->flags&kFSEventStreamCreateFlagUseCFTypes))path=[NSString stringWithUTF8String:((char**)paths)[i]];
