static void setup(Context *c,unsigned flags,BOOL queue){memset(c,0,sizeof(*c));strlcpy(c->path,"/tmp/fsevents-flush.XXXXXX",sizeof(c->path));CHECK(mkdtemp(c->path));c->flags=flags|kFSEventStreamCreateFlagFileEvents;c->names=[[NSMutableSet alloc]init];c->ready=dispatch_semaphore_create(0);if(queue){c->queue=dispatch_queue_create("flush.actual.delivery",DISPATCH_QUEUE_SERIAL);dispatch_queue_set_specific(c->queue,c,c,NULL);}else c->runloopThread=pthread_self();}
static FSEventStreamRef make(Context *c,double latency){NSArray *paths=@[[NSString stringWithUTF8String:c->path]];FSEventStreamContext context={0,c,retainInfo,releaseInfo,NULL};FSEventStreamRef stream=FSEventStreamCreate(NULL,callback,&context,(CFArrayRef)paths,kFSEventStreamEventIdSinceNow,latency,c->flags);CHECK(stream);if(c->queue)FSEventStreamSetDispatchQueue(stream,c->queue);else FSEventStreamScheduleWithRunLoop(stream,CFRunLoopGetCurrent(),CFSTR("FSEventsFlushTestMode"));return stream;}
static void waitCallback(Context *c){CHECK(dispatch_semaphore_wait(c->ready,dispatch_time(DISPATCH_TIME_NOW,2*NSEC_PER_SEC))==0);if(c->queue)dispatch_sync(c->queue,^{});}
static int streamFD(FSEventStreamRef stream){Ivar field=class_getInstanceVariable(object_getClass((id)stream),"_fd");CHECK(field);int fd;memcpy(&fd,(char*)stream+ivar_getOffset(field),sizeof(fd));if(fd>=0)CHECK(fcntl(fd,F_GETFD)&FD_CLOEXEC);return fd;}
static void waitReleased(Context *c,int fd){for(unsigned i=0;i<200;i++){if(__atomic_load_n(&c->releases,__ATOMIC_SEQ_CST)==c->retains&&fcntl(fd,F_GETFD)==-1&&errno==EBADF)return;usleep(1000);}CHECK(!"context or actual inotify fd not released");}
static void dispose(Context *c,FSEventStreamRef stream){int fd=streamFD(stream);FSEventStreamStop(stream);FSEventStreamInvalidate(stream);FSEventStreamRelease(stream);if(c->queue)dispatch_sync(c->queue,^{});waitReleased(c,fd);}
static void cleanup(Context *c){NSFileManager *fm=[NSFileManager defaultManager];CHECK([fm removeItemAtPath:[NSString stringWithUTF8String:c->path]error:NULL]);if(c->queue)dispatch_release(c->queue);dispatch_release(c->ready);[c->names release];}
typedef struct {FSEventStreamRef stream;unsigned done;CFRunLoopRef stopLoop;} SyncThread;
static void *syncThread(void *value){SyncThread *t=value;FSEventStreamFlushSync(t->stream);__atomic_store_n(&t->done,1,__ATOMIC_SEQ_CST);if(t->stopLoop)CFRunLoopStop(t->stopLoop);return NULL;}
static void *flushThread(void *value){for(unsigned i=0;i<16;i++)FSEventStreamFlushAsync((FSEventStreamRef)value);return NULL;}
static void noopPerform(void *info) {}
static void *cfLoopThread(void *value){CFRunLoopGetCurrent();usleep(10000);return NULL;}
